INSERT IGNORE INTO duranki_service_write_lock VALUES('heritage');
  
      CREATE TABLE IF NOT EXISTS heritage_catalogue(service_id VARCHAR(200) PRIMARY KEY,name VARCHAR(200) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      
      CREATE TABLE IF NOT EXISTS heritage_tenant_service(tenant_id VARCHAR(200) PRIMARY KEY,service_id VARCHAR(200) NOT NULL REFERENCES heritage_catalogue(service_id),enabled INT NOT NULL DEFAULT 0 CHECK(enabled IN(0,1))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      CREATE TABLE IF NOT EXISTS heritage_community_service(community_id VARCHAR(200) PRIMARY KEY,tenant_id VARCHAR(200) NOT NULL REFERENCES heritage_tenant_service(tenant_id),name VARCHAR(200) NOT NULL,enabled INT NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)),UNIQUE(tenant_id,community_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      CREATE TABLE IF NOT EXISTS heritage_verifier(user_id VARCHAR(200) NOT NULL,tenant_id VARCHAR(200) NOT NULL,community_id VARCHAR(200) NOT NULL,PRIMARY KEY(user_id,tenant_id,community_id),FOREIGN KEY(tenant_id,community_id) REFERENCES heritage_community_service(tenant_id,community_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      CREATE TABLE IF NOT EXISTS heritage_tree(tree_id VARCHAR(200) PRIMARY KEY,tenant_id VARCHAR(200) NOT NULL,community_id VARCHAR(200) NOT NULL,owner_user_id VARCHAR(200) NOT NULL,name VARCHAR(200) NOT NULL,created_at VARCHAR(200) NOT NULL,UNIQUE(tree_id,tenant_id,community_id),FOREIGN KEY(tenant_id,community_id) REFERENCES heritage_community_service(tenant_id,community_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      CREATE TABLE IF NOT EXISTS heritage_person(person_id VARCHAR(200) PRIMARY KEY,tree_id VARCHAR(200) NOT NULL,tenant_id VARCHAR(200) NOT NULL,community_id VARCHAR(200) NOT NULL,owner_user_id VARCHAR(200) NOT NULL,claimed_user_id VARCHAR(200),display_name VARCHAR(200) NOT NULL,name_key VARCHAR(500) NOT NULL,birth_date VARCHAR(10) NOT NULL DEFAULT '',death_date VARCHAR(10) NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',privacy VARCHAR(200) NOT NULL DEFAULT 'Private' CHECK(privacy IN('Private','Family','Community','Public')),verification VARCHAR(200) NOT NULL DEFAULT 'Unverified' CHECK(verification IN('Unverified','Family Confirmed','Community Verified','Officially Verified')),version INT NOT NULL DEFAULT 1,created_at VARCHAR(200) NOT NULL,UNIQUE(person_id,tree_id),UNIQUE(tree_id,claimed_user_id),FOREIGN KEY(tree_id,tenant_id,community_id) REFERENCES heritage_tree(tree_id,tenant_id,community_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      CREATE TABLE IF NOT EXISTS heritage_relationship(relationship_id VARCHAR(200) PRIMARY KEY,tree_id VARCHAR(200) NOT NULL,from_person_id VARCHAR(200) NOT NULL,to_person_id VARCHAR(200) NOT NULL,type VARCHAR(20) NOT NULL CHECK(type IN('parent','spouse','sibling')),kind VARCHAR(20) NOT NULL CHECK(kind IN('biological','adoptive','step','unspecified')),created_by VARCHAR(200) NOT NULL,CHECK(from_person_id<>to_person_id),UNIQUE(tree_id,from_person_id,to_person_id,type),FOREIGN KEY(from_person_id,tree_id) REFERENCES heritage_person(person_id,tree_id),FOREIGN KEY(to_person_id,tree_id) REFERENCES heritage_person(person_id,tree_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      CREATE TABLE IF NOT EXISTS heritage_invitation(invitation_id VARCHAR(200) PRIMARY KEY,person_id VARCHAR(200) NOT NULL REFERENCES heritage_person(person_id),target_user_id VARCHAR(200) NOT NULL,token_hash VARCHAR(200) NOT NULL UNIQUE,expires_at VARCHAR(200) NOT NULL,used_at VARCHAR(200),created_by VARCHAR(200) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      CREATE TABLE IF NOT EXISTS heritage_leadership(leadership_id VARCHAR(200) PRIMARY KEY,person_id VARCHAR(200) NOT NULL,tree_id VARCHAR(200) NOT NULL,title VARCHAR(200) NOT NULL,royal_house VARCHAR(200) NOT NULL,clan VARCHAR(200) NOT NULL,reign_from VARCHAR(200) NOT NULL,reign_to VARCHAR(200) NOT NULL,notes TEXT NOT NULL,FOREIGN KEY(person_id,tree_id) REFERENCES heritage_person(person_id,tree_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      CREATE TABLE IF NOT EXISTS heritage_succession(succession_id VARCHAR(200) PRIMARY KEY,tree_id VARCHAR(200) NOT NULL,predecessor_id VARCHAR(200) NOT NULL,successor_id VARCHAR(200) NOT NULL,office VARCHAR(160) NOT NULL,effective_on VARCHAR(200) NOT NULL,notes TEXT NOT NULL,CHECK(predecessor_id<>successor_id),UNIQUE(tree_id,predecessor_id,successor_id,office),FOREIGN KEY(predecessor_id,tree_id) REFERENCES heritage_person(person_id,tree_id),FOREIGN KEY(successor_id,tree_id) REFERENCES heritage_person(person_id,tree_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      CREATE TABLE IF NOT EXISTS heritage_document(document_id VARCHAR(200) PRIMARY KEY,person_id VARCHAR(200) NOT NULL REFERENCES heritage_person(person_id),filename VARCHAR(200) NOT NULL,mime VARCHAR(200) NOT NULL,content LONGBLOB NOT NULL,uploaded_by VARCHAR(200) NOT NULL,created_at VARCHAR(200) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      CREATE TABLE IF NOT EXISTS heritage_verification_history(id VARCHAR(200) PRIMARY KEY,person_id VARCHAR(200) NOT NULL REFERENCES heritage_person(person_id),status VARCHAR(200) NOT NULL,evidence TEXT NOT NULL,actor_user_id VARCHAR(200) NOT NULL,created_at VARCHAR(200) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      CREATE TABLE IF NOT EXISTS heritage_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor VARCHAR(200) NOT NULL,action VARCHAR(200) NOT NULL,record_id VARCHAR(200) NOT NULL,created_at VARCHAR(200) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      CREATE TABLE IF NOT EXISTS heritage_duplicate_review(person_id VARCHAR(200) PRIMARY KEY REFERENCES heritage_person(person_id),reason TEXT NOT NULL,actor VARCHAR(200) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
      CREATE TABLE IF NOT EXISTS heritage_enrolment(user_id VARCHAR(200) NOT NULL,tenant_id VARCHAR(200) NOT NULL,community_id VARCHAR(200) NOT NULL,service_id VARCHAR(200) NOT NULL REFERENCES heritage_catalogue(service_id),status VARCHAR(200) NOT NULL CHECK(status IN('active','cancelled')),created_at VARCHAR(200) NOT NULL,PRIMARY KEY(user_id,community_id),FOREIGN KEY(tenant_id,community_id) REFERENCES heritage_community_service(tenant_id,community_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
